import React, { useState, useRef } from "react";
import "./App.css";

// --- Icons ---
const IconCopy = () => (
  <svg className='icon' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'>
    <rect x='9' y='9' width='13' height='13' rx='2' ry='2'></rect>
    <path d='M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1'></path>
  </svg>
);

const IconCheck = () => (
  <svg
    className='icon icon-success'
    viewBox='0 0 24 24'
    fill='none'
    stroke='currentColor'
    strokeWidth='3'
    strokeLinecap='round'
    strokeLinejoin='round'
  >
    <polyline points='20 6 9 17 4 12'></polyline>
  </svg>
);

const IconUpload = () => (
  <svg className='icon icon-large' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='1' strokeLinecap='round' strokeLinejoin='round'>
    <path d='M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4'></path>
    <polyline points='17 8 12 3 7 8'></polyline>
    <line x1='12' y1='3' x2='12' y2='15'></line>
  </svg>
);

// --- Copy Component (Used for both ID and Hash) ---
const CopyField = ({ label, value }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    if (!value) return;
    navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <div className='identity-item'>
      <label className='identity-label'>{label}</label>
      <div className={`identity-box ${copied ? "copied" : ""}`} onClick={handleCopy}>
        <code className='identity-value'>{value || "Awaiting file..."}</code>
        <button className='copy-btn'>{copied ? <IconCheck /> : <IconCopy />}</button>
      </div>
    </div>
  );
};

function App() {
  const [fileData, setFileData] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [fileName, setFileName] = useState("");
  const [deviceId, setDeviceId] = useState("");
  const [deviceHash, setDeviceHash] = useState("");

  const fileInputRef = useRef(null);

  const calculateHash = async text => {
    const encoder = new TextEncoder();
    const data = encoder.encode(text);
    const hashBuffer = await crypto.subtle.digest("SHA-256", data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
  };

  const processFile = async file => {
    if (!file) return;
    setFileName(file.name);

    const text = await file.text();
    const hash = await calculateHash(text);
    // Mimicking a hardware serial generation
    const mockSerial = "SN-" + Math.random().toString(36).toUpperCase().substring(2, 12);

    setDeviceHash(hash);
    setDeviceId(mockSerial);

    const rows = text.split(/\r?\n/).filter(row => row.trim() !== "");
    const parsedData = rows.map(row => row.split(","));
    setHeaders(parsedData[0] || []);
    setFileData(parsedData.slice(1));
  };

  return (
    <div className='app-container'>
      <nav className='navbar'>
        <div className='nav-brand'>Project CSV</div>
      </nav>

      <main className='main-content'>
        {/* Identity Section */}
        {fileName && (
          <section className='identity-section'>
            <div className='section-header'>
              <h3>System Authentication</h3>
              <span className='file-name'>{fileName}</span>
            </div>
            <div className='identity-grid'>
              <CopyField label='Device Serial Number' value={deviceId} />
              <CopyField label='Hardware Hash (SHA-256)' value={deviceHash} />
            </div>
          </section>
        )}

        {/* Upload Section */}
        {!fileName && (
          <div className='upload-zone' onClick={() => fileInputRef.current.click()}>
            <input type='file' ref={fileInputRef} onChange={e => processFile(e.target.files[0])} style={{ display: "none" }} />
            <IconUpload />
            <h2>Click to upload CSV</h2>
            <p>Data is processed strictly on your local machine.</p>
          </div>
        )}

        {/* Table Section */}
        {fileData.length > 0 && (
          <div className='table-container'>
            <table>
              <thead>
                <tr>
                  {headers.map((h, i) => (
                    <th key={i}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {fileData.map((row, i) => (
                  <tr key={i}>
                    {row.map((cell, j) => (
                      <td key={j}>{cell}</td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
